import React, { useCallback, useEffect, useState, Fragment } from 'react'
import {
	Row,
	Col,
	Button,
	Skeleton,
	Modal,
	Radio,
	Form,
	Input,
	Select,
	Space,
} from 'antd'
import { useDispatch } from 'react-redux'
import { useSelector } from 'react-redux'
import { getPlans, submitPaymentInfo } from '../../Actions/Plans'

const { Option } = Select

const layout = {
	labelCol: {
		span: 8,
	},
	wrapperCol: {
		span: 16,
	},
}
const tailLayout = {
	wrapperCol: {
		offset: 8,
		span: 16,
	},
}

function PlansComponent() {
	const [isModalVisible, setIsModalVisible] = useState(false)
	const [paymenyMethod, setPaymenyMethod] = useState()
	const [number, setNumber] = useState('')
	const [date, setDate] = useState('')
	const [cvc, setCvc] = useState('')
	const [country, setCountry] = useState('united states')
	const [zipCode, setZipCode] = useState('')

	const dispatch = useDispatch()
	const { plans, token, store } = useSelector(state => state)

	console.log(store)

	useEffect(() => {
		if (!plans) {
			dispatch(getPlans())
		}
	}, [dispatch, plans])

	const toggleModal = () => {
		setIsModalVisible(!isModalVisible)
	}

	const onFinish = values => {
		const data = {
			...values,
			number,
			date,
			cvc,
			country,
			zip_code: zipCode,
		}
		console.log('Success:', data)

		dispatch(submitPaymentInfo(data, token))
	}

	const onFinishFailed = errorInfo => {
		console.log('Failed:', { ...errorInfo, country })
	}

	const formatAccountNumber = useCallback(inp => {
		const text = inp.split(' ').join('')

		if (!isNaN(text)) {
			let formatted_number = ''

			for (let i = 0; i < text.length; i++) {
				if (i > 1 && i % 4 === 0) {
					formatted_number += ' ' + text[i]
					continue
				}

				formatted_number += text[i]
			}

			setNumber(formatted_number)
		}
	}, [])

	const formatExpiryDate = useCallback(date => {
		const text = date.split('/').join('')
		const month = date.slice(0, 2)
		const year = date.split('/')[1]

		if (!isNaN(text)) {
			let formatted_date = ''

			if (+month > 12) {
				setDate('12')
				return
			}

			if (
				year &&
				year.length === 4 &&
				(+year < new Date().getFullYear() || +year > 2030)
			) {
				setDate(month + '/20')
				return
			}

			if (+text[0] > 1) {
				formatted_date = '0' + text[0] + '/'
			} else {
				for (let i = 0; i < text.length; i++) {
					if (i > 1 && i < 3) {
						formatted_date += '/' + text[i]
						continue
					}

					formatted_date += text[i]
				}
			}
			setDate(formatted_date)
		}
	}, [])

	return plans ? (
		<Fragment>
			<Space direction='vertical' size={'large'} className={'w-100'}>
				<Row gutter={30}>
					<Modal
						title='Payment Options'
						visible={isModalVisible}
						onCancel={toggleModal}
						centered
						footer={null}
						// width={700}
						okButtonProps={{ style: { display: 'none' } }}
						cancelButtonProps={{ style: { display: 'none' } }}
					>
						<p>Default payment method</p>
						<Radio checked={paymenyMethod === 1} onChange={() => setPaymenyMethod(1)}>
							**** **** **** 1111
						</Radio>

						<p className='mt-2'>Add new payment method</p>
						<Radio checked={paymenyMethod === 2} onChange={() => setPaymenyMethod(2)}>
							Add Card
						</Radio>

						{paymenyMethod === 2 && (
							<Form
								{...layout}
								name='basic'
								initialValues={{ remember: true }}
								onFinish={onFinish}
								onFinishFailed={onFinishFailed}
								className='mt-2'
							>
								<h3>Card Information</h3>
								<Form.Item
									label='Number'
									required
									rules={[{ required: true, message: 'Please input your card number!' }]}
								>
									<Input
										type='tel'
										name='number'
										pattern='\d{4}\s\d{4}\s\d{4}\s\d{4}'
										maxlength='19'
										required
										value={number}
										onChange={e => formatAccountNumber(e.target.value)}
									/>
								</Form.Item>

								<Form.Item
									label='MM/YY'
									required
									rules={[{ required: true, message: 'Please input your MM/YY!' }]}
								>
									<Input
										type='text'
										name='date'
										maxlength='7'
										pattern='(?:0[1-9]|1[0-2])/[0-9]{4}'
										required
										value={date}
										onChange={e => {
											formatExpiryDate(e.currentTarget.value)
										}}
									/>
								</Form.Item>

								<Form.Item
									label='CVC'
									required
									rules={[{ required: true, message: 'Please input your CVC' }]}
								>
									<Input
										type='number'
										name='cvc'
										maxlength='4'
										pattern='\d{4}$'
										required
										max='only 4 digits'
										value={cvc}
										onChange={e => {
											if (e.target.value.length < 5) {
												setCvc(e.target.value)
											}
										}}
									/>
								</Form.Item>

								<h3>Billing Details</h3>
								<Form.Item
									label='Card Holder Name'
									name='name'
									required
									rules={[{ required: true, message: ' Please input card holder name' }]}
								>
									<Input required />
								</Form.Item>

								<Form.Item
									label='Address'
									name='address'
									required
									rules={[{ required: true, message: ' Please input your address' }]}
								>
									<Input type='text' required />
								</Form.Item>

								<Form.Item
									label='Email'
									name='email'
									required
									rules={[{ required: true, message: ' Please input your email' }]}
								>
									<Input type='email' required />
								</Form.Item>

								<Form.Item
									label='City'
									name='city'
									required
									rules={[{ required: true, message: ' Please input your city' }]}
								>
									<Input required />
								</Form.Item>

								<Form.Item
									label='State'
									name='state'
									required
									rules={[{ required: true, message: ' Please input your state' }]}
								>
									<Input required />
								</Form.Item>

								<Form.Item label='Country'>
									<Select
										defaultValue='united states'
										name='country'
										onChange={opt => setCountry(opt)}
										value={country}
										required
									>
										<Option value='united states'>United States</Option>
										<Option value='pakistan'>Pakistan</Option>
									</Select>
								</Form.Item>

								<Form.Item
									label='Zip'
									required
									rules={[{ required: true, message: 'Please input your zip code!' }]}
								>
									<Input
										type='number'
										name='zip_code'
										maxLength='5'
										pattern='\d{5}$'
										value={zipCode}
										onChange={e => {
											if (e.target.value.length < 6) {
												setZipCode(e.target.value)
											}
										}}
										required
									/>
								</Form.Item>

								<Form.Item {...tailLayout}>
									<Button type='primary' htmlType='submit'>
										Submit
									</Button>
								</Form.Item>
							</Form>
						)}
					</Modal>
				</Row>
			</Space>

			<Row gutter={40}>
				{plans.map((plan, i) => (
					<Col className='gutter-row mb-3' xs={24} sm={24} md={12} lg={12} xl={8} key={i}>
						<div className={'pricing-box'}>
							<div className='pricing-header'>
								{plan.status === 1 && (
									<h2>
										<div>{plan.name}</div>
										<small>This is your current plan:</small>
									</h2>
								)}
								{/* <Button className={'btn-plane'} size={'large'} type='default'>
								${plan.price} / month
                            </Button> */}

								<Button
									size={'large'}
									type='primary'
									className='mt-2'
									onClick={toggleModal}
								>
									${plan.price} / month
								</Button>
							</div>
							<ul>
								{plan.terms.split('.').map(term => (
									<li key={term}>{term}</li>
								))}
							</ul>
						</div>
					</Col>
				))}
			</Row>
		</Fragment>
	) : (
		<Skeleton />
	)
}

export default PlansComponent
