import axios from 'axios'

export const getPlans = () => dispatch => {
	axios
		.get(`${process.env.REACT_APP_ENITURE_API_URL}/get_plans`)
		.then(({ data }) => {
			console.log(data)

			if (!data.error) {
				dispatch({
					type: 'GET_PLANS',
					payload: data.data,
				})
			} else {
				dispatch({
					type: 'ALERT_MESSAGE',
					showAlertMessage: true,
					alertMessage: data.message,
					alertMessageType: 'error',
				})
			}
		})
		.catch(error => {})
}

export const submitPaymentInfo = (data, token) => dispatch => {
	const config = {
		headers: {
			authorization: `Bearer ${token}`,
		},
	}
	// post http://bc.eniture.com/api/create_subscription

	axios
		.post('create_subscription', data, config)
		.then(({ data }) => {
			console.log(data)
		})
		.catch(err => console.log(err))
}
